// パスの規則は 3 つの経路 (検査 / -write-summary / -install-wrapper) で同じ):
//
//	triagecheck -record-dir /abs/docs/rt
//	triagecheck -current-dir "$(pwd)" -record-dir docs/rt
//	triagecheck -record-dir /abs/docs/rt -write-summary     # 生成サマリ (.md) を書き出す
